import { useState } from 'react'
import { useNavigate, useParams } from 'react-router'

import { Box, Button, Card, CardHeader, Divider, Typography, useMediaQuery, useTheme } from '@mui/material'
import type { GridCellParams, GridColDef, GridEventListener, GridRowSelectionModel } from '@mui/x-data-grid'
import { DataGrid } from '@mui/x-data-grid'

import { formatDate } from 'src/utils/formatDateTime'

import type { GetRecentActivityResDto } from 'src/models/activity'

import { useGetAdminActivities } from 'src/hooks/api/activityHooks'

import BulkActions from './BulkActions'

interface ActivityPostTableProps {
  handleDelete(ids: number[]): void
}

const ActivityPostTable: React.FC<ActivityPostTableProps> = ({ handleDelete }) => {
  const theme = useTheme()
  const matches = useMediaQuery(theme.breakpoints.up('sm'))
  const navigate = useNavigate()
  const { id } = useParams()
  const clubId = Number(id)

  const [selectedPosts, setSelectedPosts] = useState<GridRowSelectionModel>([])

  const { data: activityList } = useGetAdminActivities(clubId)

  const selectedBulkActions = selectedPosts.length > 0

  // type === 'activity-post'인 것만 필터링
  const activityPostList = activityList?.filter(activity => activity.type === 'activity-post') || []

  const activityPostRows =
    activityPostList.map(post => ({
      id: post.id,
      title: post.title,
      isPublic: post.isPublic ? '공개' : '비공개',
      createdAt: formatDate(new Date(post.createdAt)),
      startAt: post.startAt ? formatDate(new Date(post.startAt)) : '-'
    })) || []

  const columns: GridColDef[] = [
    { field: 'title', headerName: '제목', maxWidth: 400, flex: 1 },
    { field: 'createdAt', headerName: '작성일', maxWidth: 150, flex: 1, headerAlign: 'center', align: 'center' },
    { field: 'isPublic', headerName: '공개 여부', maxWidth: 100, flex: 1, headerAlign: 'center', align: 'center' }
  ]

  const columnsForXS: GridColDef[] = [
    { field: 'title', headerName: '제목', maxWidth: 200, flex: 1 },
    { field: 'createdAt', headerName: '작성일', maxWidth: 150, flex: 1 }
  ]

  const handleCellClick: GridEventListener<'cellClick'> = params => {
    const postId = params.row.id
    if (params.field === 'title') {
      navigate(`/manage/${clubId}/activity/${postId}`)
      return
    }
  }

  const handleAddPost = () => {
    navigate(`/manage/${clubId}/activity/register`)
  }

  return (
    <>
      <Card>
        <Box height={matches || selectedBulkActions ? '55px' : '110px'}>
          {selectedBulkActions ? (
            <Box flex={1} p={1}>
              <BulkActions selectedPosts={selectedPosts as number[]} handleDelete={handleDelete} />
            </Box>
          ) : (
            <Box
              display="flex"
              alignItems="baseline"
              flexDirection={matches ? 'row' : 'column'}
              justifyContent="space-between"
            >
              <Box display={'flex'} alignItems={'baseline'}>
                <CardHeader title="활동 포스팅 목록" />
                <Typography variant={'caption'}>포스팅 수정은 제목을 클릭해주세요</Typography>
              </Box>
              <Button
                onClick={handleAddPost}
                variant="contained"
                sx={{
                  marginRight: matches ? 1.5 : 1,
                  marginLeft: matches ? 0 : 1,
                  marginBottom: matches ? 0 : 1,
                  width: matches ? 'auto' : '95%'
                }}
              >
                포스팅 추가
              </Button>
            </Box>
          )}
        </Box>
        <Divider />
        <Box
          sx={{
            '& .title--bold': {
              fontWeight: 'bold',
              textDecoration: 'underline',
              cursor: 'pointer'
            }
          }}
        >
          <DataGrid
            autoHeight
            rows={activityPostRows}
            columns={matches ? columns : columnsForXS}
            initialState={{
              sorting: { sortModel: [{ field: 'createdAt', sort: 'desc' }] },
              pagination: { paginationModel: { pageSize: window.innerWidth >= 600 ? 10 : 5 } }
            }}
            pageSizeOptions={[5, 10, 25]}
            checkboxSelection
            onRowSelectionModelChange={newSelectionModel => {
              setSelectedPosts(newSelectionModel)
            }}
            rowSelectionModel={selectedPosts}
            onCellClick={handleCellClick}
            getCellClassName={(params: GridCellParams<GetRecentActivityResDto>) => {
              if (params.field === 'title') {
                return 'title--bold'
              } else return ''
            }}
            disableRowSelectionOnClick
          />
        </Box>
      </Card>
    </>
  )
}

export default ActivityPostTable
